-- Release 1.9 N22: a copied invitation link (Copy link) is recorded as delivery state copied, with its copy time in
-- delivery_attempted_at and final under immutable_delivery_outcome, and audited as invite.revoke plus invite.copy.
ALTER TABLE "audit_event" DROP CONSTRAINT "audit_action_known";--> statement-breakpoint
ALTER TABLE "invite" DROP CONSTRAINT "invite_delivery_shape";--> statement-breakpoint
ALTER TABLE "audit_event" ADD CONSTRAINT "audit_action_known" CHECK ("audit_event"."action" in ('student.create','student.update','student.import','grant.issue','grant.revoke','guardian.link','guardian.revoke','guardian.practice-set','tutor.cantor-set','tutor.assign','tutor.revoke','invite.issue','invite.accept','invite.revoke','invite.delivery-sent','invite.delivery-failed','context.enter','context.exit','reading.set','identity.link','identity.revoke','draft.append','note.append','service-plan.set','progress.self-check.set','progress.assessment.set','lesson-log.create','lesson-log.edit','lesson-log.delete','recording.create','recording.submit','recording.delete-request','source-assignment.set','honors.set','honoree.issue','honoree.revoke','honoree.reissue','study-voice.set','study-guide.set','study-guide.publish','study-guide-student.set','study-theme.read','tenant-settings.set','notification-preference.set','notification.unsubscribe','mcp-connection.revoke','source-identity.revoke','account-request.approve','account-request.decline','member.revoke','approver.designate','approver.revoke','service-part.finish','ceremony-done.set','ceremony-done.reverse','invite.copy'));--> statement-breakpoint
ALTER TABLE "invite" ADD CONSTRAINT "invite_delivery_shape" CHECK (("invite"."delivery_status" = 'pending' and "invite"."delivery_attempted_at" is null) or ("invite"."delivery_status" in ('sent','failed','copied') and "invite"."delivery_attempted_at" is not null));